<?php
namespace Tests\Feature;
use App\Models\{User,ConnectedAdAccount,Campaign,AdSet,Ad,PerformanceMetric};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;
class CreativeMatrixTest extends TestCase{
 use DatabaseTransactions;
 private function fixture():array{$u=User::factory()->create();$a=ConnectedAdAccount::create(['user_id'=>$u->id,'provider'=>'meta','external_account_id'=>uniqid(),'account_name'=>'Fixture','currency'=>'USD','timezone'=>'UTC','access_token'=>'fixture']);$c=Campaign::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','external_campaign_id'=>uniqid(),'name'=>'Fixture','currency'=>'USD']);$s=AdSet::create(['campaign_id'=>$c->id,'external_ad_set_id'=>'s','name'=>'Fixture']);$ad=Ad::create(['ad_set_id'=>$s->id,'external_ad_id'=>'a','name'=>'Fixture']);return[$u,$a,$c,$s,$ad];}
 public function test_matrix_matches_single_ad_analysis_without_grouping_missing_ads():void{[$u,$a,$c,$s,$ad]=$this->fixture();$empty=Ad::create(['ad_set_id'=>$s->id,'external_ad_id'=>'b','name'=>'Fixture']);for($i=21;$i>=1;$i--){$w=intdiv(21-$i,7);PerformanceMetric::create(['metadata'=>['outcome_contract'=>['version'=>'source-outcomes-1','provider'=>'meta','count_metric'=>'synthetic-purchase','value_metric'=>'synthetic-purchase-value','attribution_basis'=>'synthetic-only','value_truth'=>'provider_reported_not_verified_sales','cross_source_equivalence'=>false],'normalization_version'=>'strict-operands-1','account_metadata_source'=>'provider-discovery-explicit-1','metric_definition'=>['version'=>'meta-pixel-purchase-1','normalization'=>'strict-meta-operands-1','account_metadata_source'=>'meta-discovery-explicit-1','conversion'=>'offsite_conversion.fb_pixel_purchase','value'=>'offsite_conversion.fb_pixel_purchase']],'connected_ad_account_id'=>$a->id,'campaign_id'=>$c->id,'ad_set_id'=>$s->id,'ad_id'=>$ad->id,'provider'=>'meta','currency'=>'USD','date'=>now()->subDays($i)->toDateString(),'spend'=>100,'impressions'=>10000,'clicks'=>100-$w*20,'conversions'=>10-$w*2,'conversion_value'=>200,'frequency'=>1+$w*.3]);}$this->actingAs($u,'sanctum');$one=$this->getJson('/api/v1/analytics/creative-fatigue?ad_id='.$ad->id)->assertOk();$r=$this->getJson('/api/v1/analytics/creative-matrix?account_id='.$a->id)->assertOk()->assertJsonCount(2,'data.rows')->assertJsonPath('data.rows.0.signal','creative_fatigue_pattern')->assertJsonPath('data.rows.1.status','insufficient_data');$this->assertSame($one->json('data.windows'),$r->json('data.rows.0.windows'));$other=User::factory()->create();$this->actingAs($other,'sanctum')->getJson('/api/v1/analytics/creative-matrix?account_id='.$a->id)->assertNotFound();}
 public function test_population_cap_is_not_silent_partial():void{[$u,$a,$c,$s]=$this->fixture();for($i=0;$i<25;$i++)Ad::create(['ad_set_id'=>$s->id,'external_ad_id'=>'extra'.$i,'name'=>'Fixture']);$this->actingAs($u,'sanctum')->getJson('/api/v1/analytics/creative-matrix?account_id='.$a->id)->assertJsonPath('data.status','local_limit')->assertJsonCount(0,'data.rows');}
}
